<template><EnterpriseAuthShell><div class="auth-panel"><div class="step" data-testid="first-password-step"><b>1</b><span>首次登录安全设置</span></div><div class="eyebrow">欢迎加入</div><h2>设置您的登录密码</h2><p class="subtitle">使用初始密码验证身份，然后设置个人密码</p><el-alert v-if="error" :title="error" type="error" :closable="false" class="mb"/><el-form ref="formRef" :model="form" :rules="rules" label-position="top"><el-form-item label="当前初始密码" prop="current"><el-input v-model="form.current" type="password" show-password size="large" autocomplete="current-password" /></el-form-item><el-form-item label="新密码" prop="next"><el-input v-model="form.next" type="password" show-password size="large" autocomplete="new-password" /></el-form-item><el-form-item label="确认新密码" prop="confirm"><el-input v-model="form.confirm" type="password" show-password size="large" autocomplete="new-password" /></el-form-item><div class="rules"><b>密码要求</b><br>至少 8 个字符，并同时包含字母和数字。</div><el-button type="primary" size="large" :loading="loading" @click="submit">完成设置并继续</el-button></el-form><p class="footnote">请勿与他人共享您的密码</p></div></EnterpriseAuthShell></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{useRouter}from'vue-router';import type{FormInstance,FormRules}from'element-plus';import EnterpriseAuthShell from '@/components/enterprise/EnterpriseAuthShell.vue';import{useEnterpriseAuthStore}from'@/stores/enterpriseAuth';import{validatePassword}from'@/features/enterprise/validation';const auth=useEnterpriseAuthStore(),router=useRouter(),formRef=ref<FormInstance>(),loading=ref(false),error=ref(''),form=reactive({current:'',next:'',confirm:''});const rules:FormRules={current:[{required:true,message:'请输入当前初始密码',trigger:'blur'}],next:[{validator:(_r,_v,cb)=>{const message=validatePassword(form.next);message?cb(new Error(message)):cb()},trigger:'blur'}],confirm:[{validator:(_r,_v,cb)=>form.confirm===form.next?cb():cb(new Error('两次输入的密码不一致')),trigger:'blur'}]};async function submit(){if(!await formRef.value?.validate().catch(()=>false))return;loading.value=true;error.value='';try{await auth.changeInitialPassword(form.current,form.next);await router.replace('/enterprise/login')}catch(e){error.value=(e as{message?:string}).message||'修改失败'}finally{loading.value=false}}</script><style scoped>.mb{margin-bottom:20px}.step{display:flex;align-items:center;gap:8px;margin-bottom:16px;font-size:13px;color:#667085}.step b{display:grid;width:20px;height:20px;place-items:center;border-radius:50%;background:#2563eb;color:#fff;font-size:12px}.eyebrow{margin-bottom:6px;color:#2563eb;font-size:12px;font-weight:700;letter-spacing:.08em}.rules{margin:4px 0 20px;padding:12px;background:#f7f9fc;border-radius:6px;color:#667085;font-size:13px;line-height:1.6}.footnote{margin-top:16px;color:#98a2b3;font-size:12px;text-align:center}</style>
